namespace MockUsb {bool attached=true,allowRequest=true;uint32_t token=41,requests=0,cancels=0,lastToken=0;uint64_t capacity=128u*1024u*1024u;Tab5UsbStorage::Format lastFormat=Tab5UsbStorage::Format::Fat;Tab5UsbStorage::FormatState state=Tab5UsbStorage::FormatState::Idle;std::string status="Échec simulé du formatage";void reset(){attached=true;allowRequest=true;token++;requests=0;cancels=0;capacity=128u*1024u*1024u;state=Tab5UsbStorage::FormatState::Idle;}}
namespace Tab5UsbStorage {
bool attached(){return MockUsb::attached;}uint32_t connectionToken(){return MockUsb::token;}uint64_t capacityBytes(){return MockUsb::capacity;}FormatState formatState(){return MockUsb::state;}const char*status(){return MockUsb::status.c_str();}
bool supported(Format f){return Tab5UsbFormatPolicy::geometry(f,static_cast<uint32_t>(capacityBytes()/512),512);}
bool requestFormat(Format f,uint32_t t){++MockUsb::requests;MockUsb::lastFormat=f;MockUsb::lastToken=t;if(!attached()||t!=connectionToken()||!MockUsb::allowRequest||!supported(f)||MockUsb::state==FormatState::Waiting||MockUsb::state==FormatState::Running)return false;MockUsb::state=FormatState::Waiting;return true;}
bool cancelFormat(){++MockUsb::cancels;if(MockUsb::state!=FormatState::Waiting)return false;MockUsb::state=FormatState::Cancelled;return true;}
}
static const char*translate(const char*s){return s;}static const lv_font_t*getFont(){return font;}static uint32_t getColor(unsigned n){const unsigned m[]={0,1,4,5,3};return palette[m[std::min(n,4u)]];}
static Tab5UsbFormatUi::Hooks hooks{translate,getFont,getColor};
static void pump(){lv_tick_inc(20);lv_timer_handler();lv_obj_update_layout(screen);lv_obj_update_layout(lv_layer_top());}
static lv_obj_t* findLabel(lv_obj_t*o,const char*s){if(lv_obj_check_type(o,&lv_label_class)&&!strcmp(lv_label_get_text(o),s))return o;for(uint32_t i=0;i<lv_obj_get_child_count(o);++i)if(auto*r=findLabel(lv_obj_get_child(o,i),s))return r;return nullptr;}
static lv_obj_t* byClass(lv_obj_t*o,const lv_obj_class_t*c){if(lv_obj_check_type(o,c))return o;for(uint32_t i=0;i<lv_obj_get_child_count(o);++i)if(auto*r=byClass(lv_obj_get_child(o,i),c))return r;return nullptr;}
static lv_obj_t* button(const char*s){auto*l=findLabel(Tab5UsbFormatUi::scope(),s);check(l,"expected button caption");auto*b=lv_obj_get_parent(l);check(lv_obj_has_class(b,&lv_button_class),"caption belongs to button");return b;}
static void click(const char*s){lv_obj_send_event(button(s),LV_EVENT_CLICKED,nullptr);pump();}
static bool shown(lv_obj_t*o){for(;o;o=lv_obj_get_parent(o))if(lv_obj_has_flag(o,LV_OBJ_FLAG_HIDDEN))return false;return true;}
static bool message(const char*s){return findLabel(Tab5UsbFormatUi::scope(),s);}
static bool key(writing::Key k,bool shift=false){writing::KeyEvent e;e.key=k;e.shift=shift;return Tab5UsbFormatUi::key(e);}
static void snapshot(const std::string&name){lv_obj_invalidate(screen);lv_obj_invalidate(lv_layer_top());lv_refr_now(lvDisplay);FILE*f=fopen((shotDir+"/"+name+".ppm").c_str(),"wb");check(f,"snapshot opens");fprintf(f,"P6\n1280 720\n255\n");for(size_t i=0;i<pixels.size();i+=3){uint8_t rgb[]={pixels[i+2],pixels[i+1],pixels[i]};fwrite(rgb,1,3,f);}fclose(f);++frames;}
static void setup(){lv_init();font22=lv_tiny_ttf_create_data(fontData.data(),fontData.size(),22);font24=lv_tiny_ttf_create_data(fontData.data(),fontData.size(),24);check(font22&&font24,"shipped OS TTF loads at22/24");font22->fallback=&lv_font_montserrat_22;font24->fallback=&lv_font_montserrat_24;font=font22;Tab5UiStyle::configure(palette,8);lvDisplay=lv_display_create(1280,720);lv_display_set_color_format(lvDisplay,LV_COLOR_FORMAT_RGB888);lv_display_set_buffers(lvDisplay,pixels.data(),nullptr,pixels.size(),LV_DISPLAY_RENDER_MODE_FULL);lv_display_set_flush_cb(lvDisplay,[](lv_display_t*d,const lv_area_t*,uint8_t*){++flushes;lv_display_flush_ready(d);});screen=lv_obj_create(nullptr);lv_screen_load(screen);lv_obj_set_style_bg_color(screen,lv_color_hex(palette[0]),0);lv_obj_set_style_text_color(screen,lv_color_hex(palette[4]),0);lv_obj_remove_flag(screen,LV_OBJ_FLAG_SCROLLABLE);Tab5Focus.begin(screen,font);Tab5Focus.theme(lv_color_hex(palette[8]),lv_color_hex(palette[4]),lv_color_hex(palette[1]));auto*l=lv_label_create(screen);lv_label_set_text(l,"Stockage · Tab5OS");lv_obj_set_style_text_font(l,font,0);lv_obj_set_pos(l,20,12);}
static void testOrientation(){
 check(Tab5DisplayOrientation::rotation(false,false)==3,"landscape normal");check(Tab5DisplayOrientation::rotation(false,true)==1,"landscape reversed180");check(Tab5DisplayOrientation::rotation(true,false)==2,"portrait normal");check(Tab5DisplayOrientation::rotation(true,true)==0,"portrait reversed180");
 auto*saved=lvDisplay;lvDisplay=nullptr;displayOrientationPending=true;serviceDisplayOrientation();check(displayOrientationPending&&M5.Display.calls==0,"uninitialized display defers rotation");lvDisplay=saved;displayOrientationPending=false;serviceDisplayOrientation();check(M5.Display.calls==0,"idle does not touch display");
 lv_indev_state_t pointerState=LV_INDEV_STATE_RELEASED;auto*pointer=lv_indev_create();lv_indev_set_type(pointer,LV_INDEV_TYPE_POINTER);lv_indev_set_mode(pointer,LV_INDEV_MODE_EVENT);lv_indev_set_user_data(pointer,&pointerState);lv_indev_set_read_cb(pointer,[](lv_indev_t*i,lv_indev_data_t*d){d->point={10,10};d->state=*static_cast<lv_indev_state_t*>(lv_indev_get_user_data(i));});
 auto*keyboard=lv_indev_create();lv_indev_set_type(keyboard,LV_INDEV_TYPE_KEYPAD);lv_indev_set_mode(keyboard,LV_INDEV_MODE_EVENT);lv_indev_set_read_cb(keyboard,[](lv_indev_t*,lv_indev_data_t*d){d->key=LV_KEY_ENTER;d->state=LV_INDEV_STATE_PRESSED;});lv_indev_read(keyboard);
 for(bool upside:{false,true})for(unsigned mode=0;mode<3;++mode){settings.screenUpsideDown=upside;readerActive=mode==1;Tab5PythonReader::shown=mode==2;const auto calls=M5.Display.calls;displayOrientationPending=true;M5.Touch.touches={{false,1,1},{true,2,2}};serviceDisplayOrientation();check(displayOrientationPending&&M5.Display.calls==calls,"any physical touch holds rotation");M5.Touch.touches.clear();pointerState=LV_INDEV_STATE_PRESSED;lv_indev_read(pointer);check(lv_indev_get_state(pointer)==LV_INDEV_STATE_PRESSED,"actual LVGL pointer is pressed");serviceDisplayOrientation();check(displayOrientationPending&&M5.Display.calls==calls,"mouse or pointer press holds rotation");pointerState=LV_INDEV_STATE_RELEASED;lv_indev_read(pointer);serviceDisplayOrientation();check(!displayOrientationPending&&M5.Display.calls==calls+1,"rotation happens once after release");check(M5.Display.rotation==Tab5DisplayOrientation::rotation(mode!=0,upside),"active C++/Python reader chooses portrait and180");serviceDisplayOrientation();check(M5.Display.calls==calls+1,"no repetitive rotation redraw");}
 settings.screenUpsideDown=false;displayOrientationPending=true;M5.Touch.touches={{true,1,1}};serviceDisplayOrientation();settings.screenUpsideDown=true;M5.Touch.touches.clear();serviceDisplayOrientation();check(M5.Display.rotation==0,"deferred rotation uses most recent setting");
 for(auto dimensions:{std::pair<int,int>{1280,720},{720,1280}}){lv_display_set_resolution(lvDisplay,dimensions.first,dimensions.second);for(bool upside:{false,true}){settings.screenUpsideDown=upside;lv_indev_data_t d{};M5.Touch.touches={{true,-10,2000}};touchRead(pointer,&d);check(d.state==LV_INDEV_STATE_PRESSED&&d.point.x==0&&d.point.y==dimensions.second-1,"production touch bounds match active dimensions");M5.Touch.touches={{true,121,325}};touchRead(pointer,&d);check(d.point.x==121&&d.point.y==325,"M5 converted coordinates are not rotated twice");screenWakeTouch=true;touchRead(pointer,&d);check(d.state==LV_INDEV_STATE_RELEASED&&d.point.x==121&&d.point.y==325,"wake touch suppressed without losing last point");screenWakeTouch=false;M5.Touch.touches.clear();touchRead(pointer,&d);check(d.state==LV_INDEV_STATE_RELEASED&&d.point.x==121&&d.point.y==325,"release retains last position");}}
 M5.Touch.touches.clear();readerActive=false;Tab5PythonReader::shown=false;lv_indev_delete(pointer);lv_indev_delete(keyboard);lv_display_set_resolution(lvDisplay,1280,720);pump();
}
static void open(){check(Tab5UsbFormatUi::open(hooks),"attached volume opens format dialog");pump();check(Tab5UsbFormatUi::scope(),"modal owns focus scope");}
