 MockUsb::reset();MockUsb::capacity=8ull*1024*1024;open();check(!strcmp(lv_dropdown_get_options(byClass(Tab5UsbFormatUi::scope(),&lv_dropdown_class)),"FAT"),"small volume offers FAT only");close();
 MockUsb::reset();MockUsb::allowRequest=false;open();click("Effacer et formater");check(MockUsb::requests==1&&message("Impossible de démarrer le formatage USB")&&shown(button("Effacer et formater")),"driver rejection reported and retry allowed");MockUsb::allowRequest=true;click("Effacer et formater");check(MockUsb::requests==2&&MockUsb::state==S::Waiting,"retry requires explicit second confirmation");MockUsb::state=S::Failed;Tab5UsbFormatUi::service();check(message(MockUsb::status.c_str()),"driver failure propagated");close();
 MockUsb::reset();open();pump();unsigned before=flushes;for(unsigned n=0;n<20;++n){Tab5UsbFormatUi::service();pump();}check(flushes==before,"idle status does not invalidate/redraw modal repeatedly");check(key(writing::Key::Escape)&&!Tab5UsbFormatUi::scope(),"Escape closes modal");check(MockUsb::requests==0,"escape never starts format");
 const unsigned topChildren=lv_obj_get_child_count(lv_layer_top());for(unsigned n=0;n<120;++n){MockUsb::reset();open();key(writing::Key::Tab);key(writing::Key::Enter);check(key(writing::Key::Escape)&&Tab5UsbFormatUi::scope(),"repeated dropdown escape retains modal");key(writing::Key::Escape);pump();check(!Tab5UsbFormatUi::scope()&&lv_obj_get_child_count(lv_layer_top())==topChildren,"repeated close removes modal and dropdown objects");check(!Tab5Focus.focused(),"deleted control does not leave stale focus");}
