int main(int argc,char**argv){check(argc==3,"arguments");shotDir=argv[1];std::ifstream file(argv[2],std::ios::binary);fontData.assign(std::istreambuf_iterator<char>(file),{});setup();testOrientation();testModal();Tab5Focus.clear();lv_tiny_ttf_destroy(font22);lv_tiny_ttf_destroy(font24);lv_deinit();printf("{\"passed\":true,\"checks\":%u,\"frames\":%u,\"modalOpenCloseCycles\":120,\"fonts\":[22,24]}\n",checks,frames);}
